namespace BenchPlugin
{
    [GrasshopperCollection("Bench", "Fabrication")]
    public interface IFabricationPack : IBettaCollection
    {
        [GrasshopperMethod("Shelf Pack", "Pack rectangular parts onto sheets with a shelf algorithm")]
        (System.Collections.Generic.List<Rhino.Geometry.Curve> Outlines,
            System.Collections.Generic.List<int> Sheet,
            int SheetCount,
            double Utilization,
            System.Collections.Generic.List<int> Unplaced) ShelfPack(
            [GrasshopperParameter("Widths")] System.Collections.Generic.List<double> widths,
            [GrasshopperParameter("Heights")] System.Collections.Generic.List<double> heights,
            [GrasshopperParameter("Sheet Width", DefaultValue = 1000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", DefaultValue = 500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", DefaultValue = 5.0)] double spacing,
            [GrasshopperParameter("Rotate", DefaultValue = true)] bool rotate,
            IBettaReport report);
    }

    public class FabricationPack : IFabricationPack
    {
        public (System.Collections.Generic.List<Rhino.Geometry.Curve> Outlines,
            System.Collections.Generic.List<int> Sheet,
            int SheetCount,
            double Utilization,
            System.Collections.Generic.List<int> Unplaced) ShelfPack(
            System.Collections.Generic.List<double> widths,
            System.Collections.Generic.List<double> heights,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            bool rotate,
            IBettaReport report)
        {
            widths ??= new System.Collections.Generic.List<double>();
            heights ??= new System.Collections.Generic.List<double>();
            if (widths.Count != heights.Count)
                throw new System.ArgumentException("Widths and Heights must have the same length.");
            if (sheetWidth <= 0 || sheetHeight <= 0)
                throw new System.ArgumentException("Sheet size must be greater than zero.");
            if (spacing < 0)
                throw new System.ArgumentException("Spacing cannot be negative.");
            for (int i = 0; i < widths.Count; i++)
                if (widths[i] <= 0 || heights[i] <= 0)
                    throw new System.ArgumentException("All part sizes must be greater than zero.");

            var order = System.Linq.Enumerable.ToList(
                System.Linq.Enumerable.ThenBy(
                    System.Linq.Enumerable.OrderByDescending(System.Linq.Enumerable.Range(0, widths.Count), i => heights[i]),
                    i => i));

            var outlines = new System.Collections.Generic.List<Rhino.Geometry.Curve>();
            var sheets = new System.Collections.Generic.List<int>();
            var unplaced = new System.Collections.Generic.List<int>();
            double placedArea = 0;
            int sheetCount = 0;
            double x = 0, y = 0, shelfH = 0;
            double maxX = sheetWidth - spacing, maxY = sheetHeight - spacing;

            void Place(int index, double px, double py, double pw, double ph)
            {
                double ox = (sheetCount - 1) * (sheetWidth + 50);
                var pl = new Rhino.Geometry.Polyline(new[]
                {
                    new Rhino.Geometry.Point3d(ox + px, py, 0),
                    new Rhino.Geometry.Point3d(ox + px + pw, py, 0),
                    new Rhino.Geometry.Point3d(ox + px + pw, py + ph, 0),
                    new Rhino.Geometry.Point3d(ox + px, py + ph, 0),
                    new Rhino.Geometry.Point3d(ox + px, py, 0),
                });
                outlines.Add(pl.ToNurbsCurve());
                sheets.Add(sheetCount - 1);
                placedArea += pw * ph;
            }

            foreach (int i in order)
            {
                var sizes = new System.Collections.Generic.List<(double W, double H)> { (widths[i], heights[i]) };
                if (rotate && widths[i] != heights[i]) sizes.Add((heights[i], widths[i]));

                bool done = false;

                // current shelf
                if (sheetCount > 0 && shelfH > 0)
                {
                    foreach (var (w, h) in sizes)
                    {
                        if (h <= shelfH && x + w <= maxX)
                        {
                            Place(i, x, y, w, h);
                            x += w + spacing;
                            done = true;
                            break;
                        }
                    }
                    if (done) continue;

                    // new shelf on the current sheet
                    double ny = y + shelfH + spacing;
                    foreach (var (w, h) in sizes)
                    {
                        if (spacing + w <= maxX && ny + h <= maxY)
                        {
                            y = ny;
                            shelfH = h;
                            Place(i, spacing, y, w, h);
                            x = spacing + w + spacing;
                            done = true;
                            break;
                        }
                    }
                    if (done) continue;
                }

                // new sheet
                foreach (var (w, h) in sizes)
                {
                    if (spacing + w <= maxX && spacing + h <= maxY)
                    {
                        sheetCount++;
                        y = spacing;
                        shelfH = h;
                        Place(i, spacing, y, w, h);
                        x = spacing + w + spacing;
                        done = true;
                        break;
                    }
                }
                if (!done) unplaced.Add(i);
            }

            unplaced.Sort();
            if (unplaced.Count > 0)
                report.Warning($"{unplaced.Count} part(s) did not fit on the sheet and were left out.");

            double utilization = sheetCount == 0 ? 0 : placedArea / (sheetCount * sheetWidth * sheetHeight);
            return (outlines, sheets, sheetCount, utilization, unplaced);
        }
    }
}
